import React, { useEffect, useState } from "react";
import axios from "axios";
import { Link } from "react-router-dom";

interface Delivery {
  _id: string;
  customerId: string;
  driverId: string;
  status: string;
  location: {
    lat: number;
    lng: number;
  };
}

export default function DeliveryDashboard() {
  const [deliveries, setDeliveries] = useState<Delivery[]>([]);
  const [error, setError] = useState("");
  const [searchTerm, setSearchTerm] = useState("");

  useEffect(() => {
    axios
      .get("http://localhost:5000/api/delivery")
      .then((res) => setDeliveries(res.data))
      .catch((err) => setError("API call failed. Check your backend."));
  }, []);

  const filteredDeliveries = deliveries.filter((delivery) =>
    delivery.customerId.toLowerCase().includes(searchTerm.toLowerCase()) ||
    delivery.status.toLowerCase().includes(searchTerm.toLowerCase())
  );

  return (
    <div style={{ padding: "20px" }}>
      <h1>Delivery Dashboard</h1>

      <div style={{ marginBottom: "20px" }}>
        <Link to="/create">
          <button style={{ padding: "10px", marginRight: "10px" }}>
            + New Delivery
          </button>
        </Link>
        <Link to="/add-driver">
          <button style={{ padding: "10px", marginRight: "10px" }}>
            + Add Driver
          </button>
        </Link>
        <Link to="/drivers">
          <button style={{ padding: "10px" }}>View Drivers</button>
        </Link>
      </div>

      <input
        type="text"
        placeholder="Search by Customer ID or Status"
        value={searchTerm}
        onChange={(e) => setSearchTerm(e.target.value)}
        style={{ padding: "8px", marginBottom: "20px", width: "300px" }}
      />

      {error && <p style={{ color: "red" }}>{error}</p>}

      <table style={{ width: "100%", borderCollapse: "collapse" }}>
        <thead>
          <tr>
            <th style={th}>Customer ID</th>
            <th style={th}>Status</th>
            <th style={th}>Actions</th>
          </tr>
        </thead>
        <tbody>
          {filteredDeliveries.map((delivery) => (
            <tr key={delivery._id}>
              <td style={td}>{delivery.customerId}</td>
              <td style={td}>{delivery.status}</td>
              <td style={td}>
                <Link to={`/delivery/${delivery._id}`}>
                  <button style={{ marginRight: "8px" }}>View</button>
                </Link>
                <button>Delete</button>
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}

const th = {
  border: "1px solid #ccc",
  padding: "8px",
  background: "#f0f0f0",
  textAlign: "left" as const,
};

const td = {
  border: "1px solid #ccc",
  padding: "8px",
};
